
.chars {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.chars__pick {
  display: flex;
  gap: 4px;
  margin-bottom: 2px;
}

.chars__chip {
  flex: 1;
  padding: 5px 2px;
  background: var(--c-surface-raised);
  border: 1px solid var(--c-border);
  font-family: inherit;
  font-size: 11px;
  color: var(--c-text-muted);
  cursor: pointer;
  transition:
    color 0.25s ease,
    border-color 0.25s ease;
}

.chars__chip:hover {
  color: var(--c-text);
}

.chars__chip--active {
  font-weight: 600;
}

.field {
  display: flex;
  align-items: baseline;
  gap: 8px;
  min-width: 0;
}

.field__key {
  flex: none;
  width: 32px;
  font-size: 11px;
  letter-spacing: 0.06em;
  color: var(--c-text-muted);
}

.field__value {
  font-size: 12px;
  color: var(--c-text);
  overflow-wrap: anywhere;
}

.field__value--awakened {
  color: var(--c-accent);
  font-weight: 600;
}

.field__value--exposed {
  color: var(--c-warning);
}

.tremor {
  display: flex;
  flex-direction: column;
  gap: 5px;
  margin-top: 2px;
  padding: 7px 9px;
  background: var(--c-surface-raised);
  border-left: 2px solid var(--c-border);
  transition: border-color 0.8s ease;
}

.tremor--virtue {
  border-left-color: var(--c-primary);
}

.tremor--affliction {
  border-left-color: var(--c-warning);
}

.tremor__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
}

.tremor__count {
  font-family: var(--font-mono);
  font-size: 12px;
  color: var(--c-text);
}

.tremor__tendency {
  display: flex;
  align-items: center;
  gap: 6px;
}

.tremor__dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--c-text-muted);
  transition: background 0.8s ease;
}

.tremor--virtue .tremor__dot {
  background: var(--c-primary);
  box-shadow: 0 0 5px var(--c-primary);
}

.tremor--affliction .tremor__dot {
  background: var(--c-warning);
  box-shadow: 0 0 5px var(--c-warning);
}

.tremor__label {
  font-size: 12px;
  color: var(--c-text);
}

.tremor__note {
  font-size: 11px;
  line-height: 1.5;
  color: var(--c-text-muted);
}
