
.player {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.field {
  display: flex;
  align-items: baseline;
  gap: 8px;
  min-width: 0;
}

.field__key {
  flex: none;
  width: 32px;
  font-size: 11px;
  letter-spacing: 0.06em;
  color: var(--c-text-muted);
}

.field__value {
  font-size: 12px;
  color: var(--c-text);
  overflow-wrap: anywhere;
}

.field__value--empty {
  color: var(--c-border);
}

.field__value--awakened {
  color: var(--c-accent);
  font-weight: 600;
}

.player__hint {
  margin-top: 2px;
  font-size: 11px;
  line-height: 1.5;
  color: var(--c-text-muted);
}
