
.world {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.field {
  display: flex;
  align-items: baseline;
  gap: 8px;
  min-width: 0;
}

.field__key {
  flex: none;
  width: 32px;
  font-size: 11px;
  letter-spacing: 0.06em;
  color: var(--c-text-muted);
}

.field__value {
  font-size: 12px;
  color: var(--c-text);
  overflow-wrap: anywhere;
}

.field__value--mono {
  font-family: var(--font-mono);
  letter-spacing: 0.02em;
}

.stage {
  display: flex;
  align-items: center;
  gap: 8px;
}

.stage__body {
  display: flex;
  align-items: center;
  gap: 8px;
}

.stage__label {
  font-size: 12px;
  color: var(--c-text);
}

.stage__bars {
  display: flex;
  gap: 3px;
}

.stage__bar {
  width: 4px;
  height: 12px;
  background: var(--c-border);
  transition: background 0.6s ease;
}

.stage--calm .stage__bar--lit {
  background: var(--c-calm);
}

.stage--warning .stage__bar--lit {
  background: var(--c-warning);
}

.stage--accent .stage__bar--lit {
  background: var(--c-accent);
}

.affairs {
  display: flex;
  align-items: baseline;
  gap: 8px;
  min-width: 0;
}

.affairs__list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}

.affairs__item {
  display: flex;
  flex-direction: column;
  gap: 1px;
  padding-left: 7px;
  border-left: 1px solid var(--c-border);
}

.affairs__name {
  font-size: 12px;
  color: var(--c-text);
}

.affairs__progress {
  font-size: 11px;
  color: var(--c-text-muted);
  overflow-wrap: anywhere;
}

.affairs__empty {
  font-size: 12px;
  color: var(--c-text-muted);
}

.world__heading {
  margin-top: 5px;
  padding-bottom: 4px;
  border-bottom: 1px solid var(--c-border);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.16em;
  color: var(--c-primary);
}

.world__list {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding-left: 14px;
}

.world__item {
  font-size: 11px;
  line-height: 1.55;
  color: var(--c-text-muted);
}

.world__note {
  font-size: 11px;
  line-height: 1.55;
  color: var(--c-text-muted);
}
